#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
敖钦 AI Demo 统一启动入口：一键启动后端 (FastAPI) + 前端 (Vite)。

用法:
  python start_all.py
  python start_all.py --kill-ports    # 释放被占用的默认端口后启动
  python start_all.py --frontend-only # 仅启动前端（API 自动回落本地 Mock）
"""

from __future__ import annotations

import argparse
import os
import platform
import shutil
import signal
import socket
import subprocess
import sys
import time
import webbrowser
from pathlib import Path
from typing import Callable, Iterable, Optional
from urllib.error import URLError
from urllib.request import urlopen

# ---------------------------------------------------------------------------
# 路径
# ---------------------------------------------------------------------------

ROOT = Path(__file__).resolve().parent
BACKEND_DIR = ROOT / "backend"
FRONTEND_DIR = ROOT / "frontend"
VENV_DIR = BACKEND_DIR / ".venv"
REQUIREMENTS = BACKEND_DIR / "requirements.txt"
PACKAGE_JSON = FRONTEND_DIR / "package.json"
NODE_MODULES = FRONTEND_DIR / "node_modules"

DEFAULT_BACKEND_PORT = 8000
DEFAULT_FRONTEND_PORT = 5173
MIN_PYTHON = (3, 10)

# 项目内捆绑 Node（Windows）；其它平台可放 node-v*-linux-x64 等
BUNDLED_NODE_DIRS = [
    ROOT / ".tools" / "node-v24.14.0-win-x64",
    ROOT / ".tools" / "node-v24.14.0-linux-x64",
    ROOT / ".tools" / "node-v24.14.0-darwin-arm64",
    ROOT / ".tools" / "node-v24.14.0-darwin-x64",
]

# ---------------------------------------------------------------------------
# 输出
# ---------------------------------------------------------------------------


def info(msg: str) -> None:
    print(f"[信息] {msg}")


def ok(msg: str) -> None:
    print(f"[成功] {msg}")


def warn(msg: str) -> None:
    print(f"[警告] {msg}")


def fail(msg: str, *, hint: str = "") -> None:
    print(f"[错误] {msg}", file=sys.stderr)
    if hint:
        print(f"       → {hint}", file=sys.stderr)


def die(msg: str, *, hint: str = "", code: int = 1) -> None:
    fail(msg, hint=hint)
    sys.exit(code)


# ---------------------------------------------------------------------------
# Python
# ---------------------------------------------------------------------------


def _python_version_ok(exe: Path) -> bool:
    try:
        out = subprocess.run(
            [str(exe), "-c", "import sys; print(sys.version_info[:2])"],
            capture_output=True,
            text=True,
            timeout=15,
            check=False,
        )
        if out.returncode != 0:
            return False
        major, minor = map(int, out.stdout.strip().strip("()").replace(" ", "").split(","))
        return (major, minor) >= MIN_PYTHON
    except (OSError, ValueError, subprocess.TimeoutExpired):
        return False


def _is_windows_store_stub(exe: Path) -> bool:
    if platform.system() != "Windows":
        return False
    p = str(exe).lower()
    return "windowsapps" in p and "pythonsoftwarefoundation" not in p


def _candidate_pythons() -> list[Path]:
    seen: set[str] = set()
    candidates: list[Path] = []

    def add(path: Optional[Path]) -> None:
        if path is None:
            return
        key = str(path.resolve()) if path.exists() else str(path)
        if key in seen:
            return
        seen.add(key)
        candidates.append(path)

    add(Path(sys.executable))

    for name in ("python3", "python", "py"):
        found = shutil.which(name)
        if found:
            add(Path(found))

    if platform.system() == "Windows":
        local = Path(os.environ.get("LOCALAPPDATA", ""))
        for pattern in (
            local / "Programs" / "Python" / "Python3*" / "python.exe",
            Path(r"C:\Python3*\python.exe"),
        ):
            parent = pattern.parent
            if "*" in str(pattern):
                for match in sorted(parent.parent.glob(pattern.name), reverse=True):
                    add(match)
            else:
                add(pattern)

    venv_py = VENV_DIR / ("Scripts" if platform.system() == "Windows" else "bin") / "python.exe"
    if platform.system() != "Windows":
        venv_py = VENV_DIR / "bin" / "python"
    add(venv_py)

    return candidates


def resolve_launcher_python() -> Path:
    """用于创建 venv 的系统 Python。"""
    for exe in _candidate_pythons():
        if not exe.exists():
            continue
        if _is_windows_store_stub(exe):
            warn(f"跳过 Windows 应用商店占位程序: {exe}")
            continue
        if _python_version_ok(exe):
            return exe

    die(
        f"未找到可用的 Python {MIN_PYTHON[0]}.{MIN_PYTHON[1]}+",
        hint=(
            "请安装 Python 3.10+ 并勾选「Add to PATH」。"
            "Windows 可执行: winget install Python.Python.3.12"
        ),
    )
    raise RuntimeError("unreachable")


def venv_python() -> Path:
    scripts = "Scripts" if platform.system() == "Windows" else "bin"
    name = "python.exe" if platform.system() == "Windows" else "python"
    return VENV_DIR / scripts / name


# ---------------------------------------------------------------------------
# Node / npm
# ---------------------------------------------------------------------------


def resolve_npm() -> tuple[Path, dict[str, str]]:
    """
    返回 (npm 可执行文件, 子进程环境变量补丁)。
    优先全局 npm，其次项目 .tools 捆绑 Node。
    """
    npm = shutil.which("npm")
    if npm:
        return Path(npm), {}

    for node_dir in BUNDLED_NODE_DIRS:
        if not node_dir.is_dir():
            continue
        npm_name = "npm.cmd" if platform.system() == "Windows" else "npm"
        npm_path = node_dir / npm_name
        if npm_path.exists():
            env = os.environ.copy()
            env["PATH"] = str(node_dir) + os.pathsep + env.get("PATH", "")
            info(f"使用项目内 Node: {node_dir}")
            return npm_path, env

    die(
        "未找到 npm，且项目内无可用捆绑 Node",
        hint=(
            f"请安装 Node.js 18+，或将 Node 解压到 {ROOT / '.tools' / 'node-v24.14.0-win-x64'}。"
            "Windows 可执行: winget install OpenJS.NodeJS.LTS"
        ),
    )
    raise RuntimeError("unreachable")


# ---------------------------------------------------------------------------
# 端口
# ---------------------------------------------------------------------------


def is_port_in_use(port: int, host: str = "127.0.0.1") -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.5)
        return sock.connect_ex((host, port)) == 0


def find_free_port(start: int, attempts: int = 20) -> int:
    for port in range(start, start + attempts):
        if not is_port_in_use(port):
            return port
    die(f"在 {start}–{start + attempts - 1} 范围内找不到空闲端口")


def pids_on_port(port: int) -> list[int]:
    system = platform.system()
    pids: list[int] = []
    try:
        if system == "Windows":
            out = subprocess.check_output(
                ["netstat", "-ano"],
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=10,
            )
            token = f":{port}"
            for line in out.splitlines():
                if "LISTENING" not in line.upper() or token not in line:
                    continue
                parts = line.split()
                if parts:
                    try:
                        pids.append(int(parts[-1]))
                    except ValueError:
                        pass
        else:
            out = subprocess.check_output(
                ["lsof", "-ti", f":{port}"],
                text=True,
                timeout=10,
            )
            for line in out.split():
                try:
                    pids.append(int(line.strip()))
                except ValueError:
                    pass
    except (subprocess.CalledProcessError, FileNotFoundError, subprocess.TimeoutExpired):
        pass
    return sorted(set(p for p in pids if p > 0))


def kill_port_listeners(port: int) -> bool:
    pids = pids_on_port(port)
    if not pids:
        return False
    system = platform.system()
    killed = False
    for pid in pids:
        try:
            if system == "Windows":
                subprocess.run(
                    ["taskkill", "/PID", str(pid), "/F"],
                    check=False,
                    capture_output=True,
                    timeout=10,
                )
            else:
                os.kill(pid, signal.SIGTERM)
            killed = True
            info(f"已结束占用端口 {port} 的进程 PID={pid}")
        except OSError as exc:
            warn(f"无法结束 PID={pid}: {exc}")
    if killed:
        time.sleep(0.8)
    return killed


def ensure_port_available(
    port: int,
    *,
    name: str,
    kill: bool,
    auto_alternate: bool,
) -> int:
    if not is_port_in_use(port):
        return port

    if kill:
        if kill_port_listeners(port) and not is_port_in_use(port):
            ok(f"端口 {port} ({name}) 已释放")
            return port

    if auto_alternate:
        alt = find_free_port(port + 1)
        warn(f"端口 {port} ({name}) 已被占用，改用 {alt}")
        return alt

    die(
        f"端口 {port} ({name}) 已被占用",
        hint=f"关闭占用该端口的程序，或使用: python start_all.py --kill-ports",
    )
    raise RuntimeError("unreachable")


# ---------------------------------------------------------------------------
# 依赖安装
# ---------------------------------------------------------------------------


def run_cmd(
    cmd: list[str],
    *,
    cwd: Path,
    env: Optional[dict[str, str]] = None,
    label: str,
) -> None:
    info(f"{label}: {' '.join(cmd)}")
    try:
        result = subprocess.run(
            cmd,
            cwd=str(cwd),
            env=env,
            check=False,
        )
    except FileNotFoundError:
        die(f"{label} 失败：命令不存在", hint=" ".join(cmd))
    except OSError as exc:
        die(f"{label} 失败：{exc}", hint="检查权限、杀毒软件或磁盘空间")

    if result.returncode != 0:
        die(
            f"{label} 失败（退出码 {result.returncode}）",
            hint=_hint_for_failed_cmd(label),
        )


def _hint_for_failed_cmd(label: str) -> str:
    hints = {
        "创建虚拟环境": "确认 Python 安装完整，或以管理员身份重试",
        "安装后端依赖": (
            "可手动执行: cd backend && .venv\\Scripts\\python -m pip install -r requirements.txt\n"
            "若网络问题，可设置镜像: set PIP_INDEX_URL=https://pypi.tuna.tsinghua.edu.cn/simple"
        ),
        "安装前端依赖": (
            "可手动执行: cd frontend && npm install\n"
            "若网络问题: npm config set registry https://registry.npmmirror.com"
        ),
    }
    for key, hint in hints.items():
        if key in label:
            return hint
    return "查看上方命令输出排查原因"


def ensure_backend_venv(skip_install: bool) -> Path:
    if not BACKEND_DIR.is_dir():
        die(f"后端目录不存在: {BACKEND_DIR}")
    if not REQUIREMENTS.is_file():
        die(f"缺少依赖文件: {REQUIREMENTS}")

    py = venv_python()
    if not py.exists():
        launcher = resolve_launcher_python()
        info(f"创建虚拟环境: {VENV_DIR}")
        run_cmd(
            [str(launcher), "-m", "venv", str(VENV_DIR)],
            cwd=BACKEND_DIR,
            label="创建虚拟环境",
        )
        py = venv_python()
        if not py.exists():
            die("虚拟环境创建后仍找不到 python", hint=str(VENV_DIR))

    if skip_install:
        return py

    # 检查 uvicorn 是否已安装
    check = subprocess.run(
        [str(py), "-c", "import uvicorn, fastapi"],
        cwd=str(BACKEND_DIR),
        capture_output=True,
        timeout=30,
    )
    if check.returncode != 0:
        run_cmd(
            [str(py), "-m", "pip", "install", "-r", str(REQUIREMENTS)],
            cwd=BACKEND_DIR,
            label="安装后端依赖",
        )
    else:
        info("后端依赖已就绪，跳过 pip install")
    return py


def ensure_frontend_deps(npm: Path, env: dict[str, str], skip_install: bool) -> None:
    if not FRONTEND_DIR.is_dir():
        die(f"前端目录不存在: {FRONTEND_DIR}")
    if not PACKAGE_JSON.is_file():
        die(f"缺少前端配置: {PACKAGE_JSON}")

    if skip_install and NODE_MODULES.is_dir():
        info("跳过前端 npm install")
        return

    if not NODE_MODULES.is_dir() or not (NODE_MODULES / ".package-lock.json").exists():
        if NODE_MODULES.is_dir() and not skip_install:
            warn("node_modules 可能不完整，将执行 npm install")
        run_cmd(
            [str(npm), "install"],
            cwd=FRONTEND_DIR,
            env=env,
            label="安装前端依赖",
        )
    else:
        info("前端依赖已就绪，跳过 npm install")


# ---------------------------------------------------------------------------
# 健康检查
# ---------------------------------------------------------------------------


def wait_until(
    predicate: Callable[[], bool],
    *,
    timeout: float,
    interval: float,
    description: str,
) -> bool:
    deadline = time.time() + timeout
    while time.time() < deadline:
        if predicate():
            return True
        time.sleep(interval)
    warn(f"等待超时: {description}")
    return False


def backend_healthy(port: int) -> bool:
    try:
        with urlopen(f"http://127.0.0.1:{port}/api/health", timeout=2) as resp:
            return resp.status == 200
    except (URLError, TimeoutError, OSError):
        return False


def frontend_healthy(port: int) -> bool:
    try:
        with urlopen(f"http://127.0.0.1:{port}/", timeout=2) as resp:
            return resp.status < 500
    except (URLError, TimeoutError, OSError):
        return False


# ---------------------------------------------------------------------------
# 子进程
# ---------------------------------------------------------------------------

PROCESSES: list[subprocess.Popen] = []


def _popen_kwargs() -> dict:
    kw: dict = {
        "stdout": None,
        "stderr": None,
    }
    if platform.system() == "Windows":
        kw["creationflags"] = subprocess.CREATE_NEW_PROCESS_GROUP  # type: ignore[attr-defined]
    return kw


def start_backend(py: Path, port: int) -> subprocess.Popen:
    cmd = [
        str(py),
        "-m",
        "uvicorn",
        "app.main:app",
        "--reload",
        "--host",
        "127.0.0.1",
        "--port",
        str(port),
    ]
    info(f"启动后端 → http://127.0.0.1:{port}")
    try:
        proc = subprocess.Popen(cmd, cwd=str(BACKEND_DIR), **_popen_kwargs())
    except OSError as exc:
        die(f"无法启动后端: {exc}", hint="确认 backend/app/main.py 存在且无语法错误")
    PROCESSES.append(proc)
    return proc


def start_frontend(npm: Path, env_patch: dict[str, str], port: int, force_mock: bool) -> subprocess.Popen:
    env = os.environ.copy()
    env.update(env_patch)
    if force_mock:
        env["VITE_FORCE_MOCK"] = "true"
        warn("已启用 VITE_FORCE_MOCK，前端将强制使用本地 Mock 数据")

    cmd = [str(npm), "run", "dev", "--", "--host", "127.0.0.1", "--port", str(port)]
    info(f"启动前端 → http://127.0.0.1:{port}")
    try:
        proc = subprocess.Popen(cmd, cwd=str(FRONTEND_DIR), env=env, **_popen_kwargs())
    except OSError as exc:
        die(f"无法启动前端: {exc}", hint="确认 frontend/package.json 与 node_modules 正常")
    PROCESSES.append(proc)
    return proc


def terminate_all() -> None:
    for proc in PROCESSES:
        if proc.poll() is not None:
            continue
        try:
            if platform.system() == "Windows":
                subprocess.run(
                    ["taskkill", "/PID", str(proc.pid), "/F", "/T"],
                    capture_output=True,
                    timeout=10,
                )
            else:
                proc.terminate()
                try:
                    proc.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    proc.kill()
        except (OSError, subprocess.TimeoutExpired):
            pass
    PROCESSES.clear()


def monitor_procs(backend_proc: Optional[subprocess.Popen], frontend_proc: Optional[subprocess.Popen]) -> None:
    labels = []
    if backend_proc:
        labels.append(("后端", backend_proc))
    if frontend_proc:
        labels.append(("前端", frontend_proc))

    for name, proc in labels:
        code = proc.poll()
        if code is not None:
            die(
                f"{name} 进程已退出（代码 {code}）",
                hint=_hint_for_process_exit(name, code),
            )


def _hint_for_process_exit(name: str, code: int) -> str:
    if name == "后端":
        return (
            "常见原因: 端口冲突、依赖缺失、app 导入错误。\n"
            "可单独调试: cd backend && .venv\\Scripts\\python -m uvicorn app.main:app --port 8000"
        )
    return (
        "常见原因: 端口冲突、node_modules 损坏、Vite 配置错误。\n"
        "可尝试: cd frontend && 删除 node_modules 后重新 npm install"
    )


# ---------------------------------------------------------------------------
# 主流程
# ---------------------------------------------------------------------------


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description="敖钦 AI Demo 统一启动前后端")
    p.add_argument("--backend-port", type=int, default=DEFAULT_BACKEND_PORT)
    p.add_argument("--frontend-port", type=int, default=DEFAULT_FRONTEND_PORT)
    p.add_argument("--kill-ports", action="store_true", help="启动前结束占用默认端口的进程")
    p.add_argument("--skip-install", action="store_true", help="跳过 pip install / npm install")
    p.add_argument("--frontend-only", action="store_true", help="仅启动前端")
    p.add_argument("--backend-only", action="store_true", help="仅启动后端")
    p.add_argument("--no-browser", action="store_true", help="启动后不自动打开浏览器")
    p.add_argument("--force-mock", action="store_true", help="前端强制本地 Mock（不依赖后端）")
    p.add_argument(
        "--auto-port",
        action="store_true",
        default=True,
        help="端口被占用时自动尝试下一端口（默认开启）",
    )
    p.add_argument(
        "--no-auto-port",
        action="store_false",
        dest="auto_port",
        help="端口被占用时报错退出",
    )
    return p.parse_args()


def preflight(args: argparse.Namespace) -> tuple[int, int]:
    if not ROOT.is_dir():
        die(f"项目根目录异常: {ROOT}")

    backend_port = args.backend_port
    frontend_port = args.frontend_port

    if not args.frontend_only:
        backend_port = ensure_port_available(
            backend_port,
            name="后端",
            kill=args.kill_ports,
            auto_alternate=args.auto_port,
        )

    if not args.backend_only:
        frontend_port = ensure_port_available(
            frontend_port,
            name="前端",
            kill=args.kill_ports,
            auto_alternate=args.auto_port,
        )

    if backend_port == frontend_port and not (args.frontend_only or args.backend_only):
        die("前后端不能使用同一端口", hint="分别指定 --backend-port 与 --frontend-port")

    return backend_port, frontend_port


def main() -> None:
    args = parse_args()

    if args.frontend_only and args.backend_only:
        die("--frontend-only 与 --backend-only 不能同时使用")

    print()
    print("=" * 60)
    print("  敖钦 AI Demo — 统一启动")
    print("=" * 60)
    print()

    backend_port, frontend_port = preflight(args)

    backend_proc: Optional[subprocess.Popen] = None
    frontend_proc: Optional[subprocess.Popen] = None

    try:
        if not args.frontend_only:
            py = ensure_backend_venv(args.skip_install)
            backend_proc = start_backend(py, backend_port)
            if not wait_until(
                lambda: backend_healthy(backend_port),
                timeout=45,
                interval=0.5,
                description="后端 /api/health",
            ):
                warn("后端尚未响应健康检查，请查看终端报错；前端可能稍后可用")

        npm_path, npm_env = resolve_npm()

        if not args.backend_only:
            ensure_frontend_deps(npm_path, npm_env, args.skip_install)
            frontend_proc = start_frontend(
                npm_path, npm_env, frontend_port, args.force_mock or args.frontend_only
            )
            wait_until(
                lambda: frontend_healthy(frontend_port),
                timeout=60,
                interval=0.5,
                description="前端页面",
            )

        monitor_procs(backend_proc, frontend_proc)

        print()
        print("-" * 60)
        if backend_proc:
            ok(f"后端 API:  http://127.0.0.1:{backend_port}")
            ok(f"API 文档:  http://127.0.0.1:{backend_port}/docs")
        if frontend_proc:
            url = f"http://127.0.0.1:{frontend_port}/login"
            ok(f"前端页面:  {url}")
            if backend_proc and frontend_port == DEFAULT_FRONTEND_PORT:
                info("Vite 已将 /api 代理到后端（见 frontend/vite.config.ts）")
            if not args.no_browser:
                try:
                    webbrowser.open(url)
                except OSError:
                    warn("无法自动打开浏览器，请手动访问上述地址")
        print("-" * 60)
        print("按 Ctrl+C 停止所有服务")
        print()

        while True:
            time.sleep(1)
            monitor_procs(backend_proc, frontend_proc)

    except KeyboardInterrupt:
        print()
        info("正在停止服务…")
    finally:
        terminate_all()
        ok("所有服务已停止")


if __name__ == "__main__":
    main()

